CREATE TYPE "PollStatus" AS ENUM ('DRAFT', 'LIVE', 'CLOSED');
CREATE TABLE "Poll" ("id" UUID NOT NULL, "eventId" UUID NOT NULL, "question" VARCHAR(500) NOT NULL, "multiple" BOOLEAN NOT NULL DEFAULT false, "status" "PollStatus" NOT NULL DEFAULT 'DRAFT', "createdById" UUID NOT NULL, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "launchedAt" TIMESTAMPTZ(3), "closedAt" TIMESTAMPTZ(3), CONSTRAINT "Poll_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PollOption" ("id" UUID NOT NULL, "pollId" UUID NOT NULL, "label" VARCHAR(200) NOT NULL, "position" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "PollOption_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PollVote" ("id" UUID NOT NULL, "pollId" UUID NOT NULL, "optionId" UUID NOT NULL, "userId" UUID NOT NULL, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PollVote_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Question" ("id" UUID NOT NULL, "eventId" UUID NOT NULL, "userId" UUID NOT NULL, "content" VARCHAR(1000) NOT NULL, "moderatedAt" TIMESTAMPTZ(3), "answeredAt" TIMESTAMPTZ(3), "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Question_pkey" PRIMARY KEY ("id"));
CREATE TABLE "QuestionVote" ("id" UUID NOT NULL, "questionId" UUID NOT NULL, "userId" UUID NOT NULL, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "QuestionVote_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Poll_eventId_createdAt_idx" ON "Poll"("eventId", "createdAt"); CREATE INDEX "PollOption_pollId_position_idx" ON "PollOption"("pollId", "position"); CREATE UNIQUE INDEX "PollVote_pollId_optionId_userId_key" ON "PollVote"("pollId", "optionId", "userId"); CREATE INDEX "PollVote_pollId_userId_idx" ON "PollVote"("pollId", "userId"); CREATE INDEX "Question_eventId_createdAt_idx" ON "Question"("eventId", "createdAt"); CREATE UNIQUE INDEX "QuestionVote_questionId_userId_key" ON "QuestionVote"("questionId", "userId");
ALTER TABLE "Poll" ADD CONSTRAINT "Poll_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "Event"("id") ON DELETE CASCADE; ALTER TABLE "Poll" ADD CONSTRAINT "Poll_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT; ALTER TABLE "PollOption" ADD CONSTRAINT "PollOption_pollId_fkey" FOREIGN KEY ("pollId") REFERENCES "Poll"("id") ON DELETE CASCADE; ALTER TABLE "PollVote" ADD CONSTRAINT "PollVote_pollId_fkey" FOREIGN KEY ("pollId") REFERENCES "Poll"("id") ON DELETE CASCADE; ALTER TABLE "PollVote" ADD CONSTRAINT "PollVote_optionId_fkey" FOREIGN KEY ("optionId") REFERENCES "PollOption"("id") ON DELETE CASCADE; ALTER TABLE "PollVote" ADD CONSTRAINT "PollVote_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "Question" ADD CONSTRAINT "Question_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "Event"("id") ON DELETE CASCADE; ALTER TABLE "Question" ADD CONSTRAINT "Question_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "QuestionVote" ADD CONSTRAINT "QuestionVote_questionId_fkey" FOREIGN KEY ("questionId") REFERENCES "Question"("id") ON DELETE CASCADE; ALTER TABLE "QuestionVote" ADD CONSTRAINT "QuestionVote_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE;
